import{_ as t,c as o,o as r,aj as a}from"./chunks/framework.BlveriQe.js";const u=JSON.parse('{"title":"Interface: BlockingAcquireOptions","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/BlockingAcquireOptions.md","filePath":"reference/js-bao-wss-client/api/interfaces/BlockingAcquireOptions.md"}'),i={name:"reference/js-bao-wss-client/api/interfaces/BlockingAcquireOptions.md"};function n(s,e,c,l,h,d){return r(),o("div",null,[...e[0]||(e[0]=[a('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / BlockingAcquireOptions</p><h1 id="interface-blockingacquireoptions" tabindex="-1">Interface: BlockingAcquireOptions <a class="header-anchor" href="#interface-blockingacquireoptions" aria-label="Permalink to “Interface: BlockingAcquireOptions”">​</a></h1><p>Options for the blocking <code>locks.acquire()</code>: the lease duration plus how long to keep polling for the lock before giving up.</p><h2 id="extends" tabindex="-1">Extends <a class="header-anchor" href="#extends" aria-label="Permalink to “Extends”">​</a></h2><ul><li><a href="./AcquireOptions.html"><code>AcquireOptions</code></a></li></ul><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="owner" tabindex="-1">owner? <a class="header-anchor" href="#owner" aria-label="Permalink to “owner?”">​</a></h3><blockquote><p><code>optional</code> <strong>owner?</strong>: <code>string</code></p></blockquote><p>Who is taking this lease — a string you choose, at most 256 characters.</p><p>Presenting the owner that ALREADY holds the key, from the same caller and the same kind of caller, re-takes the lease: you get a FRESH handle and a fresh lease, and the handle the previous acquire minted stops working. That is what lets a task run whose handle died with a reset get its own lock back instead of waiting out its own successor.</p><p>Name the run (<code>ctx.runId</code> inside a function), or the work a run key coalesces — never a static string, which would let two unrelated callers re-enter each other&#39;s hold. Omit it and the lock is strictly non-reentrant, exactly as before.</p><h4 id="inherited-from" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from" aria-label="Permalink to “Inherited from”">​</a></h4><p><a href="./AcquireOptions.html"><code>AcquireOptions</code></a>.<a href="./AcquireOptions.html#owner"><code>owner</code></a></p><hr><h3 id="timeoutms" tabindex="-1">timeoutMs <a class="header-anchor" href="#timeoutms" aria-label="Permalink to “timeoutMs”">​</a></h3><blockquote><p><strong>timeoutMs</strong>: <code>number</code></p></blockquote><p>How long to wait for the lock before throwing <code>LockTimeoutError</code> (ms).</p><hr><h3 id="ttlms" tabindex="-1">ttlMs <a class="header-anchor" href="#ttlms" aria-label="Permalink to “ttlMs”">​</a></h3><blockquote><p><strong>ttlMs</strong>: <code>number</code></p></blockquote><p>Lease duration in ms (required; capped server-side at 24h).</p><h4 id="inherited-from-1" tabindex="-1">Inherited from <a class="header-anchor" href="#inherited-from-1" aria-label="Permalink to “Inherited from”">​</a></h4><p><a href="./AcquireOptions.html"><code>AcquireOptions</code></a>.<a href="./AcquireOptions.html#ttlms"><code>ttlMs</code></a></p>',25)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
